def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    opp_count = len(alive)
    expected_needers = opp_count + 1
    scarcity = supply / float(WATER_REQ * expected_needers)

    highest_prev = 0.0
    avg_prev = 0.0
    count_prev = 0
    eric_prev = 0.0
    desperate_opp = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            highest_prev = max(highest_prev, bid)
            avg_prev += bid
            count_prev += 1
            if oid == 'Eric':
                eric_prev = bid
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_opp += 1

    if count_prev > 0:
        avg_prev /= count_prev

    if scarcity >= 1.25:
        base = DAILY_SALARY * 0.32
    elif scarcity >= 1.0:
        base = DAILY_SALARY * 0.48
    elif scarcity >= 0.8:
        base = DAILY_SALARY * 0.68
    else:
        base = DAILY_SALARY * 0.9

    pressure_bid = 0.0
    if highest_prev > 0:
        pressure_bid = highest_prev + 2.0
        if eric_prev > 0 and eric_prev >= highest_prev - 1e-9:
            pressure_bid = eric_prev + 3.0
        if highest_prev >= DAILY_SALARY * 1.3:
            pressure_bid = highest_prev * 0.82

    bid = max(base, pressure_bid if pressure_bid > 0 else base)

    if desperate_opp >= 2:
        bid += 6.0
    elif desperate_opp == 0 and scarcity >= 1.0:
        bid -= 5.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, DAILY_SALARY * 0.95)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(bid, DAILY_SALARY * 0.78)

    if day >= 8 and hp > 4 and scarcity >= 1.0:
        bid *= 0.9

    reserve_floor = DAILY_SALARY * max(0, 10 - day)
    if budget > reserve_floor:
        cap = max(DAILY_SALARY * 1.35, budget * 0.28)
    else:
        cap = max(DAILY_SALARY * 0.95, budget * 0.5)

    bid = min(bid, cap, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    day = day_context['day']

    alive_opps = [o for o in opponents_status.values() if o.get('alive', True)]
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Immediate reaction to yesterday's bidding pressure
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', None)
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If others were bidding aggressively, undercut slightly to win supply cheaper.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # More conservative when low HP to avoid running out of budget.
            if my_hp > 3:
                target = highest_prev_bid - 3.0
            else:
                target = highest_prev_bid - 1.0
        else:
            # If pressure was low, bid enough to secure water.
            target = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)
    else:
        # No trace info: use a baseline bid.
        target = DAILY_SALARY * 0.55 if my_hp > 2 else DAILY_SALARY * 0.85

    # Safety caps: never exceed budget; also avoid extreme overspending.
    # Supply is in [15,25]; water requirement is 9 so at most one/limited winners.
    # Use a soft cap around 1.1*DAILY_SALARY for aggressive days.
    soft_cap = DAILY_SALARY * 1.1
    bid = float(min(my_budget, max(0.0, min(target, soft_cap))))

    # If we are very low on HP, prioritize survival.
    if my_hp <= 2:
        bid = float(min(my_budget, max(bid, DAILY_SALARY * 0.9)))

    # If supply is high within range, we can bid slightly lower.
    if supply >= 21.0:
        bid = float(max(0.0, bid - 2.0))

    return bid

def get_bid(day_context, my_status, opponents_status):
